Trigger.script:
local title = matches[2]
local line = getCurrentLine()
local start = line:find(title, 1, true)

if start then
  local mudletStart = start - 1
  local len = #title

  -- Royal purple -> gold
--    local primary   = {190, 25, 40}
--  local secondary = {230, 180, 70}
  --local primary   = {105, 40, 210}
  --local secondary = {255, 220, 45}
local primary   = {180, 20, 40}
local secondary = {230, 180, 70}
  --local primary   = {80, 90, 220}
  --local secondary = {245, 215, 120}
  --local primary   = {155, 70, 255}
  --local secondary = {255, 215, 65}

  for i = 1, len do
    local ratio = 0

    if len > 1 then
      ratio = (i - 1) / (len - 1)
    end

    local r = math.floor(primary[1] + (secondary[1] - primary[1]) * ratio)
    local g = math.floor(primary[2] + (secondary[2] - primary[2]) * ratio)
    local b = math.floor(primary[3] + (secondary[3] - primary[3]) * ratio)

    selectSection(mudletStart + i - 1, 1)
    setFgColor(r, g, b)
  end

  resetFormat()
  deselect()
end

